"612 :     private void findEigenvalues()
613 :         throws InvalidMatrixException {
614 : 
615 :         // compute splitting points
616 :         List<Integer> splitIndices = computeSplits();
617 : 
618 :         // find realEigenvalues in each block
619 :         realEigenvalues = new double[main.length];
620 :         imagEigenvalues = new double[main.length];
621 :         int begin = 0;
622 :         for (final int end : splitIndices) {
623 :             final int n = end - begin;
624 :             switch (n) {
625 : 
