"691 :     private List<Integer> computeSplits() {
692 : 
693 :         final List<Integer> list = new ArrayList<Integer>();
694 : 
695 :         // splitting preserving relative accuracy
696 :         double absDCurrent = Math.abs(main[0]);
697 :         for (int i = 0; i < secondary.length; ++i) {
698 :             final double absDPrevious = absDCurrent;
699 :             absDCurrent = Math.abs(main[i + 1]);
700 :             final double max = splitTolerance * Math.sqrt(absDPrevious * absDCurrent);
701 :             if (Math.abs(secondary[i]) <= max) {
702 :                 list.add(i + 1);
703 :                 secondary[i] = 0;
704 :                 squaredSecondary[i] = 0;
705 :             }
706 :         }
707 : 
708 :         list.add(secondary.length + 1);
709 :         return list;
