"1253 :     private void ldlTDecomposition(final double lambda, final int index, final int n) {
1254 :         double di = main[index] - lambda;
1255 :         work[0] = Math.abs(di);
1256 :         for (int i = 1; i < n; ++i) {
1257 :             final int    fourI = 4 * i;
1258 :             final double eiM1  = secondary[index + i - 1];
1259 :             final double ratio = eiM1 / di;
1260 :             work[fourI - 2] = ratio * ratio * Math.abs(di);
1261 :             di = (main[index + i] - lambda) - eiM1 * ratio;
1262 :             work[fourI] = Math.abs(di);
1263 :         }
