"823 :     private void processGeneralBlock(final int n)
824 :         throws InvalidMatrixException {
825 : 
826 :         // check decomposed matrix data range
827 :         double sumOffDiag = 0;
828 :         for (int i = 0; i < n - 1; ++i) {
829 :             final int fourI = 4 * i;
830 :             final double ei = work[fourI + 2];
831 :             sumOffDiag += ei;
832 :         }
833 : 
834 :         if (sumOffDiag == 0) {
835 :             // matrix is already diagonal
836 :             return;
837 :         }
838 : 
839 :         // initial checks for splits (see Parlett & Marques section 3.3)
840 :         flipIfWarranted(n, 2);
841 : 
842 :         // two iterations with Li's test for initial splits
843 :         initialSplits(n);
844 : 
845 :         // initialize parameters used by goodStep
846 :         tType = 0;
847 :         dMin1 = 0;
848 :         dMin2 = 0;
849 :         dN    = 0;
850 :         dN1   = 0;
851 :         dN2   = 0;
852 :         tau   = 0;
853 : 
854 :         // process split segments
855 :         int i0 = 0;
856 :         int n0 = n;
857 :         while (n0 > 0) {
858 : 
859 :             // retrieve shift that was temporarily stored as a negative off-diagonal element
860 :             sigma    = (n0 == n) ? 0 : -work[4 * n0 - 2];
861 :             sigmaLow = 0;
862 : 
863 :             // find start of a new split segment to process
864 :             double offDiagMin = (i0 == n0) ? 0 : work[4 * n0 - 6];
865 :             double offDiagMax = 0;
866 :             double diagMax    = work[4 * n0 - 4];
867 :             double diagMin    = diagMax;
868 :             i0 = 0;
869 :             for (int i = 4 * (n0 - 2); i >= 0; i -= 4) {
870 :                 if (work[i + 2] <= 0) {
871 :                     i0 = 1 + i / 4;
872 :                     break;
873 :                 }
874 :                 if (diagMin >= 4 * offDiagMax) {
875 :                     diagMin    = Math.min(diagMin, work[i + 4]);
876 :                     offDiagMax = Math.max(offDiagMax, work[i + 2]);
877 :                 }
878 :                 diagMax    = Math.max(diagMax, work[i] + work[i + 2]);
879 :                 offDiagMin = Math.min(offDiagMin, work[i + 2]);
880 :             }
881 :             work[4 * n0 - 2] = offDiagMin;
882 : 
883 :             // lower bound of Gershgorin disk
884 :             dMin = -Math.max(0, diagMin - 2 * Math.sqrt(diagMin * offDiagMax));
885 : 
886 :             pingPong = 0;
887 :             int maxIter = 30 * (n0 - i0);
888 :             for (int k = 0; i0 < n0; ++k) {
889 :                 if (k >= maxIter) {
890 :                     throw new InvalidMatrixException(new MaxIterationsExceededException(maxIter));
891 :                 }
892 : 
893 :                 // perform one step
894 :                 n0 = goodStep(i0, n0);
895 :                 pingPong = 1 - pingPong;
896 : 
897 :                 // check for new splits after "ping" steps
898 :                 // when the last elements of qd array are very small
899 :                 if ((pingPong == 0) && (n0 - i0 > 3) &&
900 :                     (work[4 * n0 - 1] <= TOLERANCE_2 * diagMax) &&
901 :                     (work[4 * n0 - 2] <= TOLERANCE_2 * sigma)) {
902 :                     int split  = i0 - 1;
903 :                     diagMax    = work[4 * i0];
904 :                     offDiagMin = work[4 * i0 + 2];
905 :                     double previousEMin = work[4 * i0 + 3];
906 :                     for (int i = 4 * i0; i < 4 * n0 - 16; i += 4) {
907 :                         if ((work[i + 3] <= TOLERANCE_2 * work[i]) ||
908 :                             (work[i + 2] <= TOLERANCE_2 * sigma)) {
909 :                             // insert a split
910 :                             work[i + 2]  = -sigma;
911 :                             split        = i / 4;
912 :                             diagMax      = 0;
913 :                             offDiagMin   = work[i + 6];
914 :                             previousEMin = work[i + 7];
915 :                         } else {
916 :                             diagMax      = Math.max(diagMax, work[i + 4]);
917 :                             offDiagMin   = Math.min(offDiagMin, work[i + 2]);
918 :                             previousEMin = Math.min(previousEMin, work[i + 3]);
919 :                         }
920 :                     }
921 :                     work[4 * n0 - 2] = offDiagMin;
922 :                     work[4 * n0 - 1] = previousEMin;
923 :                     i0 = split + 1;
924 :                 }
925 :             }
926 : 
927 :         }
928 : 
929 :     }"

